public final class String {
    private final byte[] value; // character data stored here
    private int hash; // cached hashCode

    public String(String original) {
        this.value = original.value; // safe to share because immutable
        this.hash = original.hash;
    }

    public String concat(String str) {
        // Returns NEW String, doesn't modify this object
        byte[] newValue = Arrays.copyOf(value, value.length + str.value.length);
        System.arraycopy(str.value, 0, newValue, value.length, str.value.length);
        return new String(newValue);
    }

    public char charAt(int index) {
        return (char) value[index]; // read-only access, no setter
    }
}

public class ReportGenerator {
    // SLOW: Creates N String objects, copies characters N² times
    public String generateReportSlow(List<String> rows) {
        String report = "";
        for (String row : rows) {
            report = report + row + "\n"; // new String each iteration
        }
        return report;
    }

    // FAST: Reuses single StringBuilder, copies each character once
    public String generateReportFast(List<String> rows) {
        var builder = new StringBuilder(rows.size() * 50);
        for (String row : rows) {
            builder.append(row).append("\n"); // mutates internal buffer
        }
        return builder.toString();
    }

