public final class CustomerOrder {
    private final Long orderId;
    private final String customerName;
    private final List<String> items; // mutable type needs defense

    public CustomerOrder(Long orderId, String customerName, List<String> items) {
        this.orderId = orderId;
        this.customerName = customerName;
        // Defensive copy: external list changes won't affect us
        this.items = List.copyOf(items);
    }

    public Long getOrderId() { return orderId; }
    public String getCustomerName() { return customerName; }

    public List<String> getItems() {
        // Returns unmodifiable view, safe to expose
        return items; // List.copyOf already made it immutable
    }
}

