public final class String {
    private final byte[] value; // character data
    private int hash; // cached hashCode, 0 means not computed yet

    public int hashCode() {
        int h = hash; // read cached value
        if (h == 0 && value.length > 0) {
            // Compute hash from characters only on first call
            for (byte b : value) {
                h = 31 * h + b;
            }
            hash = h; // cache for future calls
        }
        return h;
    }
}

