// Hypothetical attack if String weren't final
class MaliciousString extends String {
    private boolean checked = false;

    @Override
    public char charAt(int index) {
        if (!checked) {
            // Return safe path during security check
            return "/home/user/data.txt".charAt(index);
        } else {
            // Return dangerous path after check passes
            return "/etc/passwd".charAt(index);
        }
    }
}

