public class FileAccess {
    public void openFile(String path) {
        if (securityCheck(path)) { // sees /home/user/data.txt
            // MaliciousString changes behavior here
            Files.readAllBytes(Paths.get(path)); // opens /etc/passwd!
        }
    }
}
